import{_ as s,o as t,c as o,a2 as r}from"./chunks/framework.7R1OEGYz.js";const g=JSON.parse('{"title":"Sharing a session","description":"","frontmatter":{},"headers":[],"relativePath":"sharing.md","filePath":"sharing.md","lastUpdated":1793867713000}'),a={name:"sharing.md"};function n(i,e,h,d,l,c){return t(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="sharing-a-session" tabindex="-1">Sharing a session <a class="header-anchor" href="#sharing-a-session" aria-label="Permalink to &quot;Sharing a session&quot;">​</a></h1><p>Sharing lets other people open a session you own: they follow what the agent does and, if you allow it, type into it as well. You can share one session with a named user, hand out a secret link, or share a whole project, so that every session in it opens for a user or a group. Child sessions follow their parent&#39;s share. You stay the owner either way: settings, lifecycle and sharing remain yours.</p><p><strong>Edition:</strong> Enterprise · <strong>Who:</strong> the session or project owner shares; recipients act as <strong>Viewer</strong> or <strong>Collaborator</strong></p><h2 id="licence-required" tabindex="-1">Licence required <a class="header-anchor" href="#licence-required" aria-label="Permalink to &quot;Licence required&quot;">​</a></h2><p>Sharing needs an active Enterprise licence. Without one:</p><ul><li>The <strong>Share</strong> dialog shows an <em>Enterprise feature</em> card (&quot;Sharing sessions with other users needs an active enterprise license.&quot;). Admins get an <strong>Activate a license →</strong> link; everyone else is asked to contact an administrator. The project dialog shows the same card.</li><li>The API answers sharing calls with <strong>402</strong> and the MCP tools fail with <code>license_required</code>.</li><li>Existing shares stay stored but open nothing. Recipients no longer see the sessions, and share links show the invalid-link message. Once a licence is active again, the shares work again.</li></ul><h2 id="roles-viewer-and-collaborator" tabindex="-1">Roles: Viewer and Collaborator <a class="header-anchor" href="#roles-viewer-and-collaborator" aria-label="Permalink to &quot;Roles: Viewer and Collaborator&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>Viewer</th><th>Collaborator</th><th>Owner</th></tr></thead><tbody><tr><td>Watch the terminal and the Workspace conversation, read the transcript</td><td>✓</td><td>✓</td><td>✓</td></tr><tr><td>See the workspace diff and the integrated browser</td><td>✓</td><td>✓</td><td>✓</td></tr><tr><td>List, preview and download session files</td><td>✓</td><td>✓</td><td>✓</td></tr><tr><td>Type in the terminal and composer, resize the terminal</td><td>—</td><td>✓</td><td>✓</td></tr><tr><td>Answer the agent&#39;s questions and CLI menus</td><td>—</td><td>✓</td><td>✓</td></tr><tr><td>Control the integrated browser, use its clipboard</td><td>—</td><td>✓</td><td>✓</td></tr><tr><td>Upload files, paste attachments, delete ready files</td><td>—</td><td>✓</td><td>✓</td></tr><tr><td>Tool approval prompts (<strong>Allow</strong> / <strong>Deny</strong>), secret requests, <strong>Messages</strong>, auto approve</td><td>—</td><td>—</td><td>✓</td></tr><tr><td><strong>Edit session</strong>, shell, pause, resume, delete, duplicate, organize</td><td>—</td><td>—</td><td>✓</td></tr><tr><td>Manage sharing, the git identity and the MCP restrictions</td><td>—</td><td>—</td><td>✓</td></tr></tbody></table><p>A Viewer&#39;s session view is marked <strong>Read-only</strong>, and a Viewer&#39;s connection sends nothing to the agent, not even terminal resizes. Only the uploader or the owner can cancel an unfinished upload.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Anyone who can type into a session can read whatever it holds, including the files in <code>~/.secrets</code> and its secret environment variables. Give Collaborator only to people you would hand the session&#39;s credentials to.</p></div><h2 id="share-with-a-named-user" tabindex="-1">Share with a named user <a class="header-anchor" href="#share-with-a-named-user" aria-label="Permalink to &quot;Share with a named user&quot;">​</a></h2><p>Open the session and click <strong>↗ Share</strong> in its top bar, or the <strong>↗</strong> button on its row in the sidebar. In the <strong>Share session</strong> dialog:</p><ol><li>Type a name or username (at least two characters) or an exact email address. The dialog suggests up to 8 users who have signed in to this hub before. You are never suggested yourself, and email addresses are never displayed: an email only finds someone when typed in full.</li><li>Click a suggestion. The share always goes to the sign-in username.</li><li>Choose <strong>Viewer</strong> or <strong>Collaborator</strong> and click <strong>Add</strong>.</li></ol><p>The person must have signed in at least once. Otherwise the dialog shows &quot;No matching user…&quot; and the API answers <code>unknown_recipient</code>.</p><p>The recipient finds the session under <strong>Shared with me</strong> (see below) or opens it directly at <code>https://hub.example.com/s/&lt;session-id&gt;</code>. If they are signed out, the sign-in brings them back to that address. Signed in with the wrong account, they see &quot;This session is unavailable or is not shared with this account&quot;.</p><p><strong>For operators:</strong> the suggestions reveal the names and usernames of everyone who has signed in. To turn them off, set <code>sharing.userSuggestionsEnabled: false</code> in the chart (default <code>true</code>). Owners then have to enter the exact username or email.</p><h2 id="share-links" tabindex="-1">Share links <a class="header-anchor" href="#share-links" aria-label="Permalink to &quot;Share links&quot;">​</a></h2><p>Under <strong>Share by link</strong>, choose a role and, optionally, an expiry date, then click <strong>Create link</strong>. The dialog shows the full link once (&quot;Copy this one-time link now; it cannot be shown again&quot;). Anyone holding it opens the session at <code>/shared/&lt;token&gt;</code> with that role, without signing in. Treat it like a password.</p><ul><li>Each link is listed by its id, where you can change its role or expiry (<strong>Save</strong>) or <strong>Revoke</strong> it. An expiry must be in the future.</li><li>A link opens exactly that session, never its child sessions, and it never appears in anyone&#39;s session list.</li><li>A link&#39;s files are read-only, even with the Collaborator role: no uploads, no deleting.</li><li>An invalid, expired or revoked link shows the same message: &quot;This share link is invalid, expired, or revoked. Ask the session owner for a new link.&quot;</li></ul><p><strong>For operators:</strong> links are built from the chart value <code>frontendOrigin</code>, which defaults to <code>https://</code> plus <code>ingress.host</code>. Behind a proxy, set it to the public address. The hub must be served at the root of its origin; a path prefix is not supported.</p><h2 id="changing-a-role-and-revoking-access" tabindex="-1">Changing a role and revoking access <a class="header-anchor" href="#changing-a-role-and-revoking-access" aria-label="Permalink to &quot;Changing a role and revoking access&quot;">​</a></h2><p>In the dialog, each person has a role selector with <strong>Viewer</strong>, <strong>Collaborator</strong> and <strong>Remove</strong>. Changes apply on the recipient&#39;s next request; their list drops the session within a few seconds. A terminal connection the recipient already has open stays open until it reconnects.</p><h2 id="child-sessions-inherit-the-share" tabindex="-1">Child sessions inherit the share <a class="header-anchor" href="#child-sessions-inherit-the-share" aria-label="Permalink to &quot;Child sessions inherit the share&quot;">​</a></h2><p>When a shared session&#39;s agent starts child sessions, everyone who can open the parent opens the children with the same role. Nothing is copied: revoking the parent&#39;s share closes the children too, and a share added later reaches children that already exist.</p><p>When several grants reach a session, the strongest applies: Collaborator beats Viewer. A grant only ever adds access, so a Viewer share on a child does not narrow a Collaborator share on its parent. To take access away, remove the grant that gives it.</p><h2 id="share-a-whole-project" tabindex="-1">Share a whole project <a class="header-anchor" href="#share-a-whole-project" aria-label="Permalink to &quot;Share a whole project&quot;">​</a></h2><p>In the sidebar, hover over a project&#39;s header and click <strong>⇪</strong> (<em>Share project</em>). Share with a <strong>User</strong> or a <strong>Group</strong>, as Viewer or Collaborator:</p><ul><li>The share opens every session of yours in the project, including sessions created later and their child sessions, even children outside the project.</li><li><strong>Group</strong> offers only identity-provider groups you belong to. Recipients&#39; group membership is updated each time they sign in.</li><li>A share on a single session adds to the project share, never reduces it. To keep someone out of one session, move it out of the project.</li><li>Removing a project share, moving a session out of the project or deleting the project closes access on the next request. The session&#39;s own <strong>Share</strong> dialog lists the project&#39;s shares read-only, marked &quot;via project&quot;.</li></ul><p>Project shares are managed only in the web app. Personal API tokens and the MCP tools cannot create or change them, but recipients can still reach the sessions through both.</p><p>Not tested: group shares with a real OIDC provider. Group membership was simulated in testing.</p><h2 id="shared-with-me" tabindex="-1">&quot;Shared with me&quot; <a class="header-anchor" href="#shared-with-me" aria-label="Permalink to &quot;&quot;Shared with me&quot;&quot;">​</a></h2><p>Sessions shared with you, directly or through a project, appear in the sidebar and on the <strong>Sessions</strong> page in the group <strong>Shared with me</strong>. Child sessions are nested under their parent (&quot;child of …&quot;). Each row shows your role, the owner (&quot;by …&quot;) and, where it applies, &quot;via project …&quot;. The list updates every five seconds.</p><p>Status filters such as <strong>Question open</strong> and <strong>Waiting</strong> find shared sessions for every role. <strong>Needs you</strong> on Home and the <strong>SESSIONS</strong> badge count a shared session only if you are Collaborator, because a Viewer cannot answer.</p><h2 id="mcp-restrictions-for-the-whole-session" tabindex="-1">MCP restrictions for the whole session <a class="header-anchor" href="#mcp-restrictions-for-the-whole-session" aria-label="Permalink to &quot;MCP restrictions for the whole session&quot;">​</a></h2><p>Under <strong>MCP security</strong> in the <strong>Share</strong> dialog, you can block MCP servers (one name per line) or exact tool names such as <code>mcp__server__tool</code>, then click <strong>Save MCP policy</strong>. The block applies to everyone who works in the session, including you, from the next MCP call on. It also covers child sessions, and it is a hard deny even with auto approve on. Tool results already in the transcript stay there.</p><p>The block is enforced for Claude, Codex and OpenCode sessions, which check every tool call with the hub. Cursor and OpenClaw sessions have no such check, so the block does not reach them. (Read from the code; not tested in a running Cursor or OpenClaw session.)</p><h2 id="managing-shares-from-an-api-client" tabindex="-1">Managing shares from an API client <a class="header-anchor" href="#managing-shares-from-an-api-client" aria-label="Permalink to &quot;Managing shares from an API client&quot;">​</a></h2><p>With a personal API token (<code>Authorization: Bearer oah_…</code>) you can manage shares of your own sessions:</p><table tabindex="0"><thead><tr><th>Method and path</th><th>Purpose</th></tr></thead><tbody><tr><td><code>GET /api/remote/sessions/shared</code></td><td>Sessions shared with you</td></tr><tr><td><code>GET /api/remote/sessions/{id}/shares</code></td><td>People and links (never the link tokens)</td></tr><tr><td><code>POST /api/remote/sessions/{id}/shares/users</code></td><td><code>{ &quot;recipient&quot;, &quot;role&quot; }</code>: share, or change the role</td></tr><tr><td><code>DELETE /api/remote/sessions/{id}/shares/users/{recipient}</code></td><td>Revoke a person</td></tr><tr><td><code>POST /api/remote/sessions/{id}/shares/links</code></td><td><code>{ &quot;role&quot;, &quot;expiresAt&quot; }</code>: returns an absolute <code>url</code>, once</td></tr><tr><td><code>DELETE /api/remote/sessions/{id}/shares/links/{linkId}</code></td><td>Revoke a link</td></tr></tbody></table><p>The AgentHub MCP server (stdio and remote, see <a href="/docs/mcp">MCP clients</a>) offers the same as tools: <code>session_share</code>, <code>session_unshare</code>, <code>session_share_link</code> and <code>session_shares</code>. Roles are <code>Viewer</code> (the default) or <code>Collaborator</code>. A misspelt role fails with <code>invalid_role</code> instead of being guessed. To revoke a link, use the DELETE route above or the dialog. An agent cannot share its own session: the MCP server inside a session pod has no sharing tools. For how a session&#39;s agent can reach sessions shared with its owner, see <a href="/docs/session-tools">Session tools</a>.</p><h2 id="when-a-session-is-deleted" tabindex="-1">When a session is deleted <a class="header-anchor" href="#when-a-session-is-deleted" aria-label="Permalink to &quot;When a session is deleted&quot;">​</a></h2><p>Deleting a session removes its shares, links and MCP restrictions with it. Its links then return 404 and show the invalid-link message, and the session disappears from recipients&#39; lists. Child sessions you keep lose the access they inherited from the deleted parent.</p>',42)])])}const u=s(a,[["render",n]]);export{g as __pageData,u as default};
